  1	import { LiveAnnouncer } from '@angular/cdk/a11y';
  2	import { Combobox, ComboboxPopup, ComboboxWidget } from '@angular/aria/combobox';
  3	import { Listbox, Option } from '@angular/aria/listbox';
  4	import {
  5	  ApplicationRef,
  6	  ChangeDetectionStrategy,
  7	  Component,
  8	  ElementRef,
  9	  Injector,
 10	  afterNextRender,
 11	  computed,
 12	  effect,
 13	  inject,
 14	  input,
 15	  model,
 16	  output,
 17	  signal,
 18	  untracked,
 19	  viewChild,
 20	} from '@angular/core';
 21	import type { FormValueControl } from '@angular/forms/signals';
 22	import { LucideCheck, LucideChevronDown, LucideX } from '@lucide/angular';
 23	import type { SelectOption } from './field-config.model';
 24	import { PanelOverlay } from './panel-overlay';
 25	import { SEARCH_THRESHOLD, filterOptions, normaliseForSearch } from './select-search';
 26	
 27	/** The empty value of a select: its shown text, never an option (US-04-BR-05). */
 28	export const SELECT_PROMPT = 'Selecciona una opción';
 29	const SEARCH_PLACEHOLDER = 'Escribe para buscar';
 30	
 31	/**
 32	 * The design-system select (ADR-0012 section 3): a WAI-ARIA combobox with a listbox popup built
 33	 * on `@angular/aria`. Below `SEARCH_THRESHOLD` options it is select-only (a `<button>`); from there
 34	 * it is editable and filters the list (an `<input>`). The focused element is the one the field's
 35	 * `<label for>` points at. The model is the option `value` (or `''`), exactly as the native select
 36	 * held it (US-04-BR-07). It never declares `invalid`, `required`, `touched` or `disabled` inputs:
 37	 * the form passes what is shown (ADR-0012 section 5).
 38	 */
 39	@Component({
 40	  selector: 'app-custom-select',
 41	  imports: [Combobox, ComboboxPopup, ComboboxWidget, Listbox, Option, PanelOverlay, LucideCheck, LucideChevronDown, LucideX],
 42	  changeDetection: ChangeDetectionStrategy.OnPush,
 43	  styleUrl: './custom-select.css',
 44	  templateUrl: './custom-select.html',
 45	})
 46	export class CustomSelect implements FormValueControl<string> {
 47	  /** The stored value: an option `value`, or `''`. */
 48	  readonly value = model<string>('');
 49	  /** Emitted when the focus leaves the control (Signal Forms marks the field touched). */
 50	  readonly touch = output<void>();
 51	
 52	  readonly controlId = input.required<string>();
 53	  readonly labelId = input.required<string>();
 54	  readonly options = input.required<readonly SelectOption[]>();
 55	  readonly hasIcon = input(false);
 56	  readonly ariaRequired = input(false);
 57	  readonly ariaInvalid = input(false);
 58	  readonly ariaDescribedby = input<string | null>(null);
 59	
 60	  protected readonly prompt = SELECT_PROMPT;
 61	  protected readonly searchPlaceholder = SEARCH_PLACEHOLDER;
 62	  protected readonly expanded = signal(false);
 63	  /** The text of the editable combobox: the chosen label while closed, what is typed while open. */
 64	  protected readonly text = signal('');
 65	  /** The typed filter; `null` until the person types, so opening shows every option. */
 66	  protected readonly filterText = signal<string | null>(null);
 67	
 68	  protected readonly searchable = computed(() => this.options().length >= SEARCH_THRESHOLD);
 69	  protected readonly selectedLabel = computed(() => this.options().find((o) => o.value === this.value())?.label ?? '');
 70	  protected readonly shown = computed(() => filterOptions(this.options(), this.filterText() ?? ''));
 71	  protected readonly selection = computed(() => (this.value() === '' ? [] : [this.value()]));
 72	
 73	  private readonly control = viewChild<ElementRef<HTMLElement>>('control');
 74	  private readonly listbox = viewChild(Listbox);
 75	  private readonly announcer = inject(LiveAnnouncer);
 76	  private readonly injector = inject(Injector);
 77	  private readonly appRef = inject(ApplicationRef);
 78	  private typed = '';
 79	  private typedAt = 0;
 80	  private pendingActive: string | null = null;
 81	
 82	  constructor() {
 83	    // Closed, the editable box shows the chosen label and no filter is kept (Escape, leaving, choosing).
 84	    effect(() => {
 85	      if (this.expanded()) return;
 86	      const label = this.selectedLabel();
 87	      untracked(() => {
 88	        this.filterText.set(null);
 89	        this.text.set(label);
 90	      });
 91	    });
 92	    // Opening a searchable select with a chosen label selects it, so typing replaces it.
 93	    effect(() => {
 94	      if (!this.expanded() || !this.searchable()) return;
 95	      const typing = untracked(() => this.filterText() !== null);
 96	      if (typing) return;
 97	      afterNextRender(() => (this.control()?.nativeElement as HTMLInputElement | undefined)?.select(), { injector: this.injector });
 98	    });
 99	    // The result count, or the empty text, is announced politely while filtering (US-04-AC-07).
100	    effect(() => {
101	      const typed = this.filterText();
102	      if (typed === null) return;
103	      const count = this.shown().length;
104	      untracked(() => this.announcer.announce(count === 0 ? this.emptyText(typed) : count === 1 ? '1 opción' : `${count} opciones`, 'polite'));
105	    });
106	    // The first match is active after every change of the filter, or the match of the first key typed on a closed select.
107	    effect(() => {
108	      const listbox = this.listbox();
109	      this.shown();
110	      if (!listbox) return;
111	      const typing = untracked(() => this.filterText() !== null);
112	      const wanted = untracked(() => this.pendingActive);
113	      if (!typing && wanted === null) return;
114	      afterNextRender(() => {
115	        if (wanted !== null) {
116	          const index = this.shown().findIndex((o) => o.value === wanted);
117	          if (index >= 0) listbox.gotoIndex(index);
118	          this.pendingActive = null;
119	        } else {
120	          listbox.gotoFirst();
121	        }
122	      }, { injector: this.injector });
123	    });
124	  }
125	
126	  protected emptyText(typed: string): string {
127	    return `No encontramos opciones para «${typed.trim()}».`;
128	  }
129	
130	  protected optionId(option: SelectOption): string {
131	    return `${this.controlId()}-option-${option.value}`;
132	  }
133	
134	  focus(options?: FocusOptions): void {
135	    this.control()?.nativeElement.focus(options);
136	  }
137	
138	  protected openOnClick(): void {
139	    if (!this.expanded()) this.expanded.set(true);
140	    this.render();
141	  }
142	
143	  /**
144	   * Renders now, at the end of the current event, so the list exists and has its first option active
145	   * before the next key arrives (a key sent right after "open" would otherwise be consumed by the
146	   * list setting up its default state).
147	   */
148	  private render(): void {
149	    queueMicrotask(() => this.appRef.tick());
150	  }
151	
152	  /**
153	   * The combobox toggles on a click. A click that carries no pointer (`detail` 0: a script, or
154	   * assistive technology activating the control) only ever opens the list, so activating an open
155	   * select leaves it open; a mouse or touch press on an open one still closes it.
156	   */
157	  protected onButtonClick(event: MouseEvent): void {
158	    if (event.detail !== 0) return;
159	    // After the combobox's own toggle, whatever the order of the two listeners.
160	    queueMicrotask(() => {
161	      if (!this.expanded()) this.expanded.set(true);
162	    });
163	    this.render();
164	  }
165	
166	  protected onInput(event: Event): void {
167	    this.filterText.set((event.target as HTMLInputElement).value);
168	  }
169	
170	  protected onKeydown(event: KeyboardEvent): void {
171	    this.render();
172	    if (this.searchable() && event.ctrlKey && !event.metaKey && !event.altKey && event.key.toLowerCase() === 'a') {
173	      // Ctrl+A selects the text on every platform (on macOS it would move to the line start).
174	      event.preventDefault();
175	      (event.target as HTMLInputElement).select();
176	      return;
177	    }
178	    if (this.expanded()) {
179	      if (event.key === 'Tab') {
180	        this.commit(this.activeValue());
181	        this.expanded.set(false);
182	      } else if (event.key === 'Enter' || (event.key === ' ' && !this.searchable())) {
183	        // Choosing the active option, also when it is the one already chosen (the list would toggle it off).
184	        const active = this.activeValue();
185	        if (active !== null) {
186	          event.preventDefault();
187	          this.choose(active);
188	        }
189	      }
190	      return;
191	    }
192	    if ((event.altKey && event.key === 'ArrowDown') || (this.searchable() && event.key === 'Enter')) {
193	      // Enter in the collapsed search box opens the list and never submits the form (US-04-AC-06).
194	      event.preventDefault();
195	      this.expanded.set(true);
196	      return;
197	    }
198	    // A printable key on a collapsed select-only select opens it on the first match (US-04-AC-06).
199	    if (!this.searchable() && event.key.length === 1 && event.key !== ' ' && !event.ctrlKey && !event.metaKey && !event.altKey) {
200	      const now = Date.now();
201	      this.typed = now - this.typedAt > 500 ? event.key : this.typed + event.key;
202	      this.typedAt = now;
203	      const wanted = normaliseForSearch(this.typed);
204	      this.pendingActive = this.options().find((o) => normaliseForSearch(o.label).startsWith(wanted))?.value ?? null;
205	      this.expanded.set(true);
206	    }
207	  }
208	
209	  /** The option the list has as active, read from the list itself (the attribute lags one render). */
210	  private activeValue(): string | null {
211	    const id = this.listbox()?.activeDescendant();
212	    return this.options().find((o) => this.optionId(o) === id)?.value ?? null;
213	  }
214	
215	  /**
216	   * The list reports a new selection when a row is chosen. An empty selection is never a choice:
217	   * the list also reports it when a filter removes the chosen option from view.
218	   */
219	  protected pick(values: readonly string[]): void {
220	    if (values.length > 0) this.choose(values[0]);
221	  }
222	
223	  /** Chooses an option: stores its value, closes the list and keeps the focus on the control. */
224	  protected choose(value: string): void {
225	    this.commit(value);
226	    this.expanded.set(false);
227	    this.focus();
228	  }
229	
230	  protected close(): void {
231	    this.expanded.set(false);
232	    this.focus();
233	  }
234	
235	  private commit(value: string | null): void {
236	    if (value !== null && value !== '' && value !== this.value()) this.value.set(value);
237	  }
238	
239	  protected onFocusout(): void {
240	    this.touch.emit();
241	  }
242	}
