 28	export class DateField implements FormValueControl<string> {
 29	  readonly value = model<string>('');
 30	  readonly touch = output<void>();
 31	
 32	  readonly controlId = input.required<string>();
 33	  readonly config = input.required<FieldConfig>();
 34	  readonly localeTag = input.required<string>();
 35	  readonly hasIcon = input(false);
