 45	  private readonly box = viewChild.required<ElementRef<HTMLInputElement>>('box');
 46	  private readonly opener = viewChild.required<ElementRef<HTMLButtonElement>>('opener');
 47	  private lastTyped = '';
 48	  protected readonly calendarOpen = signal(false);
 49	
 50	  /** What the text box shows, kept in step with the model. */
 51	  protected readonly text = transformedValue<string, string>(this.value, {
 52	    parse: (typed) => {
 53	      this.lastTyped = typed;
 54	      const iso = parseDateText(typed);
 55	      return iso === null ? { value: '', error: { kind: 'parse', message: '' } } : { value: iso };
 56	    },
 57	    format: (iso) => ((parseDateText(this.lastTyped) ?? '') === iso ? this.lastTyped : formatDateText(iso)),
