  1	import { DIALOG_DATA, DialogRef } from '@angular/cdk/dialog';
  2	import { Listbox, Option } from '@angular/aria/listbox';
  3	import { ChangeDetectionStrategy, Component, ElementRef, Injector, afterNextRender, computed, inject, signal, viewChild } from '@angular/core';
  4	import { LucideCalendarDays, LucideChevronLeft, LucideChevronRight, LucideX } from '@lucide/angular';
  5	import { isDayDisabled, latestValidDate, longDateName, monthGrid, monthName, moveToYear, nextFocusDate, partsOf, shortWeekdays, yearRange } from './calendar-dates';
  6	import type { FieldConfig } from './field-config.model';
  7	
  8	/** What the date field hands to the dialog (ADR-0012 section 4). */
  9	export interface CalendarData {
 10	  config: FieldConfig;
 11	  today: Date;
 12	  localeTag: string;
 13	  /** The stored ISO date, or `''`. */
 14	  value: string;
 15	  /** The id of the element that names the dialog: the visible month and year. */
 16	  titleId: string;
 17	  /** A bottom sheet (narrow screens) or an anchored popover. */
 18	  sheet: boolean;
 19	}
 20	
 21	const MOVE_KEYS = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown'];
 22	
 23	/**
 24	 * The content of the calendar dialog: a WAI-ARIA date picker (ADR-0012 section 4). The month grid is
 25	 * a roving-tabindex grid driven by the pure `nextFocusDate`; the year selector is a listbox on
 26	 * `@angular/aria`. A day is disabled if and only if the field's validator rejects it. The dialog
 27	 * closes with the chosen ISO date, or with nothing.
 28	 */
 29	@Component({
 30	  selector: 'app-calendar',
 31	  imports: [Listbox, Option, LucideCalendarDays, LucideChevronLeft, LucideChevronRight, LucideX],
 32	  changeDetection: ChangeDetectionStrategy.OnPush,
 33	  host: { '(keydown)': 'onKeydown($event)' },
 34	  styleUrl: './calendar.css',
 35	  templateUrl: './calendar.html',
 36	})
 37	export class Calendar {
 38	  protected readonly data = inject<CalendarData>(DIALOG_DATA);
 39	  private readonly ref = inject<DialogRef<string | undefined>>(DialogRef);
 40	  private readonly injector = inject(Injector);
 41	  private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');
 42	
 43	  private readonly latest = latestValidDate(this.data.config, this.data.today);
 44	  private readonly stored = this.data.value !== '' && !isDayDisabled(this.data.config, this.data.value, this.data.today) ? this.data.value : null;
 45	  /** The day that has the roving tabindex and the keyboard focus. */
 46	  protected readonly focused = signal(this.stored ?? this.latest);
 47	  protected readonly choosingYear = signal(false);
 48	
 49	  protected readonly years = computed(() => {
 50	    const { from, to } = yearRange(this.data.config, this.data.today);
 51	    return Array.from({ length: to - from + 1 }, (_, i) => from + i);
 52	  });
 53	  protected readonly title = computed(() => monthName(this.focused(), this.data.localeTag));
 54	  protected readonly selectedYear = computed(() => [partsOf(this.focused()).year]);
 55	  protected readonly short = shortWeekdays(this.data.localeTag);
 56	  protected readonly grid = computed(() => {
 57	    const { year, month } = partsOf(this.focused());
 58	    const { weekdays, weeks } = monthGrid(year, month, this.data.localeTag);
 59	    return {
 60	      weekdays,
 61	      weeks: weeks.map((week) =>
 62	        week.map((iso) =>
 63	          iso === null
 64	            ? null
 65	            : {
 66	                iso,
 67	                day: partsOf(iso).day,
 68	                name: longDateName(iso, this.data.localeTag),
 69	                selected: iso === this.data.value,
 70	                disabled: isDayDisabled(this.data.config, iso, this.data.today),
 71	              },
 72	        ),
 73	      ),
 74	    };
 75	  });
 76	
 77	  constructor() {
 78	    afterNextRender(() => this.focusDay());
 79	  }
 80	
 81	  protected focusDay(): void {
 82	    const cell = this.root().nativeElement.querySelector<HTMLElement>('[role="gridcell"][tabindex="0"]');
 83	    cell?.focus();
 84	  }
 85	
 86	  protected moveMonth(direction: -1 | 1): void {
 87	    this.focused.set(nextFocusDate(this.focused(), direction === -1 ? 'PageUp' : 'PageDown', false, this.data.localeTag));
 88	  }
