 99	    if (event.key === 'Enter' || event.key === ' ') {
100	      event.preventDefault();
101	      this.choose(from);
102	      return;
103	    }
104	    if (!MOVE_KEYS.includes(event.key)) return;
105	    event.preventDefault();
106	    this.focused.set(nextFocusDate(from, event.key, event.shiftKey, this.data.localeTag));
