108	  }
109	
110	  protected choose(iso: string): void {
111	    if (isDayDisabled(this.data.config, iso, this.data.today)) return;
112	    this.ref.close(iso);
113	  }
114	
115	  protected toggleYears(): void {
116	    this.choosingYear.update((v) => !v);
