119	    }
120	  }
121	
122	  protected pickYear(years: readonly number[]): void {
123	    const year = years[0] ?? partsOf(this.focused()).year;
124	    this.focused.set(moveToYear(this.focused(), year));
125	    this.choosingYear.set(false);
126	    afterNextRender(() => this.focusDay(), { injector: this.injector });
127	  }
128	
129	  protected close(): void {
130	    this.ref.close(undefined);
131	  }
132	}
  1	<div class="calendar" #root [class.calendar--sheet]="data.sheet">
  2	  <div class="head">
  3	    <span class="title" [id]="data.titleId" aria-live="polite">{{ title() }}</span>
