 11	      </button>
 12	      <button type="button" class="secondary" aria-label="Mes siguiente" (click)="moveMonth(1)">
 13	        <svg lucideChevronRight></svg>
 14	      </button>
 15	    </div>
 16	  </div>
 17	
 18	  @if (choosingYear()) {
 19	    <ul ngListbox class="year-list" focusMode="roving" selectionMode="explicit" aria-label="Año" [wrap]="false" [value]="selectedYear()" (valueChange)="pickYear($event)">
 20	      @for (year of years(); track year) {
 21	        <li ngOption class="year" [value]="year" [label]="'' + year">{{ year }}</li>
 22	      }
 23	    </ul>
 24	  } @else {
 25	    <table class="grid" role="grid" [attr.aria-labelledby]="data.titleId">
 26	      <thead>
 27	        <tr>
 28	          @for (name of grid().weekdays; track $index) {
 29	            <th role="columnheader" scope="col" class="weekday" [attr.aria-label]="name">
 30	              <span aria-hidden="true">{{ short[$index] }}</span>
 31	            </th>
 32	          }
 33	        </tr>
 34	      </thead>
 35	      <tbody>
 36	        @for (week of grid().weeks; track $index) {
 37	          <tr>
 38	            @for (cell of week; track $index) {
 39	              @if (cell; as day) {
 40	                <td
 41	                  role="gridcell"
 42	                  class="day"
 43	                  [class.day--selected]="day.selected"
 44	                  [class.day--disabled]="day.disabled"
 45	                  [attr.tabindex]="day.iso === focused() ? 0 : -1"
 46	                  [attr.aria-label]="day.name"
 47	                  [attr.aria-selected]="day.selected ? 'true' : 'false'"
 48	                  [attr.aria-disabled]="day.disabled ? 'true' : null"
 49	                  (click)="choose(day.iso)"
 50	                  (keydown)="onGridKeydown($event, day.iso)"
 51	                >
 52	                  {{ day.day }}
 53	                </td>
 54	              } @else {
 55	                <td role="presentation" aria-hidden="true"></td>
 56	              }
 57	            }
 58	          </tr>
 59	        }
 60	      </tbody>
 61	    </table>
 62	  }
 63	
 64	  <button type="button" class="secondary close" (click)="close()">
 65	    <svg lucideX></svg>
 66	    <span>Cerrar</span>
 67	  </button>
 68	</div>
