content.content:
  1	/*
  2	 * Global styles: reset, element defaults, focus, buttons, the input look shared by every control,
  3	 * skeletons, the page enter animation and the panels of the CDK overlays (ADR-0010, ADR-0013).
  4	 * Semantic and component tokens only; no primitive and no loose value (US-04-BR-01).
  5	 */
  6	
  7	*,
  8	*::before,
  9	*::after {
 10	  box-sizing: border-box;
 11	}
 12	
 13	html {
 14	  -webkit-text-size-adjust: 100%;
 15	}
 16	
 17	body {
 18	  margin: 0;
 19	  background-color: var(--color-bg);
 20	  background-image: var(--texture-dots);
 21	  background-size: var(--texture-dots-gap) var(--texture-dots-gap);
 22	  color: var(--color-text);
 23	  font-family: var(--font-text);
 24	  font-size: var(--text-body);
 25	  line-height: var(--leading-body);
 26	}
 27	
 28	/* ---- Type ------------------------------------------------------------------------------- */
 29	
 30	h1,
 31	h2,
 32	h3 {
 33	  margin: 0;
 34	  font-family: var(--font-display);
 35	  font-weight: var(--weight-bold);
 36	}
 37	
 38	/* The page heading: large, heavy, semi-expanded, with a soft gradient (ADR-0010 section 5). */
 39	h1 {
 40	  font-size: var(--text-display);
 41	  font-weight: var(--weight-heavy);
 42	  font-stretch: var(--text-display-stretch);
 43	  line-height: var(--leading-display);
 44	  letter-spacing: var(--tracking-display);
 45	  background-image: var(--gradient-display-text);
 46	  background-clip: text;
 47	  -webkit-background-clip: text;
 48	  color: transparent;
 49	  -webkit-text-fill-color: transparent;
 50	}
 51	
 52	h1:focus:not(:focus-visible) {
 53	  outline: none;
 54	}
 55	
 56	h2 {
 57	  font-size: var(--text-heading);
 58	  font-stretch: var(--text-heading-stretch);
 59	  line-height: var(--leading-heading);
 60	}
 61	
 62	h3 {
 63	  font-size: var(--text-subheading);
 64	  font-stretch: var(--text-subheading-stretch);
 65	  line-height: var(--leading-subheading);
 66	}
 67	
 68	p {
 69	  margin: 0;
 70	}
 71	
 72	strong {
 73	  font-weight: var(--weight-semibold);
 74	}
 75	
 76	/* Gradient text has a solid fallback when the system draws its own colours. */
 77	@media (forced-colors: active) {
 78	  h1 {
 79	    background-image: none;
 80	    color: CanvasText;
 81	    -webkit-text-fill-color: currentColor;
 82	  }
 83	}
 84	
 85	/* ---- Focus ------------------------------------------------------------------------------ */
 86	
 87	:focus-visible {
 88	  outline: var(--focus-ring-width) solid var(--color-focus);
 89	  outline-offset: var(--focus-ring-offset);
 90	}
 91	
 92	/* ---- Utilities -------------------------------------------------------------------------- */
 93	
 94	.visually-hidden {
 95	  position: absolute;
 96	  width: var(--border-width-hairline);
 97	  height: var(--border-width-hairline);
 98	  margin: calc(-1 * var(--border-width-hairline));
 99	  padding: 0;
100	  overflow: hidden;
101	  clip-path: inset(50%);
102	  white-space: nowrap;
103	  border: 0;
104	}
105	
106	/* Every icon is a decorative SVG sized by tokens (ADR-0010 section 7). */
107	.lucide {
108	  flex: none;
109	  width: var(--size-icon);
110	  height: var(--size-icon);
111	}
112	
113	.lucide-small {
114	  width: var(--size-icon-small);
115	  height: var(--size-icon-small);
116	}
117	
118	/* ---- Page frame ------------------------------------------------------------------------- */
119	
120	.page {
121	  max-width: var(--size-form-max);
122	  margin: 0 auto;
123	  padding: var(--space-5) var(--space-4) var(--space-7);
124	}
125	
126	.page > h1 {
127	  margin-bottom: var(--space-5);
128	}
129	
130	@media (min-width: 37.5em) {
131	  .page {
132	    padding: var(--space-6) var(--space-5) var(--space-8);
133	  }
