content.content:
     1	<main class="page page--plans" animate.enter="page-enter" [attr.aria-busy]="status() === 'loading' ? 'true' : null">
     2	  <h1 id="plans-heading" #heading tabindex="-1">Elige tu plan</h1>
     3	  @switch (status()) {
     4	    @case ('loading') {
     5	      <p role="status" class="visually-hidden">Cargando planes…</p>
     6	      <div class="plans" aria-hidden="true">
     7	        <span class="skeleton skeleton--plan"></span>
     8	        <span class="skeleton skeleton--plan"></span>
     9	        <span class="skeleton skeleton--plan"></span>
    10	      </div>
    11	    }
    12	    @case ('error') {
    13	      <app-load-error message="No pudimos cargar los planes. Intenta de nuevo." (retry)="load()" />
    14	    }
    15	    @case ('empty') {
    16	      <p role="status" class="message message--help">No hay planes disponibles para tu país en este momento.</p>
    17	    }
    18	    @case ('ready') {
    19	      <div
    20	        class="plans"
    21	        role="radiogroup"
    22	        aria-labelledby="plans-heading"
    23	        aria-required="true"
    24	        [attr.aria-describedby]="showChoosePlan() ? 'choose-plan-message' : null"
    25	      >
    26	        @for (item of items(); track item.plan.key) {
