// Reviewer probe 1: field icons on selects, radio pixels, combobox keyboard paths.
const { chromium } = require('/Users/cristiansabogal/Proyectos/multicountry-car-insurance/frontend/node_modules/playwright');
const BASE = 'http://localhost:8080';

async function state(page, label) {
  return page.evaluate((label) => {
    const lab = [...document.querySelectorAll('label')].find((l) => l.textContent.replace('*', '').trim() === label);
    const el = document.getElementById(lab.htmlFor);
    const ad = el.getAttribute('aria-activedescendant');
    const ctrl = el.getAttribute('aria-controls');
    return {
      tag: el.tagName, expanded: el.getAttribute('aria-expanded'), controls: ctrl,
      controlsExists: ctrl ? !!document.getElementById(ctrl) : null,
      active: ad ? document.getElementById(ad)?.textContent.trim() : null,
      shown: el.tagName === 'INPUT' ? el.value : el.textContent.trim(),
      focused: document.activeElement === el,
      stored: JSON.parse(sessionStorage.getItem('quote-wizard') || '{}')?.step1?.values ?? null,
      url: location.pathname,
      announce: document.querySelector('.cdk-live-announcer-element')?.textContent ?? null,
      options: [...document.querySelectorAll('[role=option]')].map((o) => o.textContent.trim() + (o.getAttribute('aria-selected') === 'true' ? '*' : '')),
    };
  }, label);
}
const log = (k, v) => console.log(k.padEnd(48), JSON.stringify(v));

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, locale: 'es-CO' });
  await page.goto(BASE + '/co/datos');
  await page.getByLabel(/Tipo de documento/).first().waitFor();

  // A. icons on selects
  const icons = await page.evaluate(() => [...document.querySelectorAll('.control__icon')].map((icon) => {
    const r = icon.getBoundingClientRect();
    const hit = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
    const field = icon.closest('.field').querySelector('label').textContent.trim();
    return { field, hitTag: hit.tagName.toLowerCase(), hitClass: hit.getAttribute('class'), visible: icon.contains(hit) };
  }));
  for (const i of icons) log('A icon ' + i.field, i);

  // C. select-only "Tipo de documento"
  const tipo = page.locator('#field-documentType');
