  await tipo.evaluate((el) => el.dispatchEvent(new MouseEvent('click', { bubbles: true, detail: 0 }))); await page.waitForTimeout(150); log('open + synthetic click', await state(page, L));
  // Playwright's dispatchEvent is not trusted either; try CDP-trusted keyboard? Not possible for detail 0 click; record.
  await page.keyboard.press('Escape');
