  const boxes = await page.evaluate(() => [...document.querySelectorAll('.control__icon')].map((icon) => {
    const r = icon.getBoundingClientRect();
    return { field: icon.closest('.field').querySelector('label').textContent.replace('*','').trim(), x: r.x + window.scrollX, y: r.y + window.scrollY, w: r.width, h: r.height,
      z: getComputedStyle(icon).zIndex, hostPos: getComputedStyle(icon.nextElementSibling).position, hostTag: icon.nextElementSibling.tagName.toLowerCase() };
  }));
