    const max = await probe.evaluate(async (d) => {
      const img = new Image(); img.src = 'data:image/png;base64,' + d; await img.decode();
      const c = document.createElement('canvas'); c.width = img.width; c.height = img.height; const x = c.getContext('2d'); x.drawImage(img, 0, 0);
      const px = x.getImageData(0, 0, c.width, c.height).data; let m = 0; for (let i = 0; i < px.length; i += 4) m = Math.max(m, px[i] + px[i+1] + px[i+2]); return m / 3;
    }, buf.toString('base64'));
    log('icon ' + b.field, { maxLum: Math.round(max), z: b.z, nextSibling: b.hostTag, nextPos: b.hostPos, size: [b.w, b.h] });
  }
  await browser.close();
})();
