const { chromium, BASE, log } = require('./common.cjs');
const desc = (page) => page.evaluate(() => {
  const a = document.activeElement;
  const dlg = document.querySelector('[role=dialog]');
  return {
    focus: a.getAttribute('aria-label') || a.textContent.trim().slice(0, 30) || a.tagName, role: a.getAttribute('role'),
    inDialog: dlg ? dlg.contains(a) : null, title: document.querySelector('[role=dialog]')?.getAttribute('aria-labelledby') && document.getElementById(document.querySelector('[role=dialog]').getAttribute('aria-labelledby'))?.textContent.trim(),
    box: document.getElementById('field-birthDate')?.value, stored: JSON.parse(sessionStorage.getItem('quote-wizard') || '{}')?.step1?.values?.birthDate,
  };
});
(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, locale: 'es-CL' });
  const page = await ctx.newPage();
  await page.clock.setFixedTime(new Date('2026-11-21T12:00:00'));
  await page.goto(BASE + '/cl/datos');
  const opener = page.getByRole('button', { name: 'Elegir fecha: Fecha de nacimiento' });
  await opener.focus();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(300);
  log('open (Enter)', await desc(page));
  log('dialog attrs', await page.evaluate(() => { const d = document.querySelector('[role=dialog]'); return { modal: d.getAttribute('aria-modal'), hiddenSiblings: [...document.body.children].filter((c) => !c.classList.contains('cdk-overlay-container')).map((c) => c.tagName + ':' + c.getAttribute('aria-hidden')) }; }));
  const seq = [];
  for (let i = 0; i < 7; i++) { await page.keyboard.press('Tab'); seq.push((await desc(page)).focus); }
  log('Tab cycle', seq);
  const back = [];
  for (let i = 0; i < 7; i++) { await page.keyboard.press('Shift+Tab'); back.push((await desc(page)).focus); }
  log('Shift+Tab cycle', back);
  // go to grid
  await page.locator('[role=gridcell][tabindex="0"]').focus();
  for (const k of ['ArrowRight', 'ArrowDown', 'Home', 'End', 'PageUp', 'Shift+PageUp', 'ArrowLeft']) { await page.keyboard.press(k); await page.waitForTimeout(50); log('grid ' + k, await desc(page)); }
  // year selector
  await page.getByRole('button', { name: 'Elegir año' }).click();
  await page.waitForTimeout(100);
  log('year list focus', await desc(page));
  log('year list info', await page.evaluate(() => { const l = document.querySelector('[role=listbox]'); return { label: l.getAttribute('aria-label'), first: l.querySelector('[role=option]').textContent.trim(), last: [...l.querySelectorAll('[role=option]')].pop().textContent.trim(), selected: l.querySelector('[aria-selected=true]')?.textContent.trim() }; }));
  await page.keyboard.press('Home'); log('year Home', await desc(page));
  await page.keyboard.type('1990'); await page.waitForTimeout(100); log('year typeahead 1990', await desc(page));
  await page.keyboard.press('Enter'); await page.waitForTimeout(100); log('year Enter', await desc(page));
  // escape inside year list
  await page.getByRole('button', { name: 'Elegir año' }).click(); await page.waitForTimeout(100);
  await page.keyboard.press('Escape'); await page.waitForTimeout(200); log('Escape in year list', await desc(page));
  // reopen, choose a day with Enter
  await opener.focus(); await page.keyboard.press('Enter'); await page.waitForTimeout(300);
  log('reopen focus', await desc(page));
  // try clicking a disabled day
  const dis = page.locator('[role=gridcell][aria-disabled=true]').first();
  if (await dis.count()) { await dis.click(); await page.waitForTimeout(100); log('click disabled day', await desc(page)); }
  // backdrop click
  await page.mouse.click(5, 5); await page.waitForTimeout(200); log('backdrop click', await desc(page));
  await opener.focus(); await page.keyboard.press('Enter'); await page.waitForTimeout(300);
  await page.keyboard.press('ArrowLeft'); await page.keyboard.press('Enter'); await page.waitForTimeout(200);
  log('choose with Enter', await desc(page));
  // typed hint and opener name; focus visible style on day
  await opener.focus(); await page.keyboard.press('Enter'); await page.waitForTimeout(300);
  log('day focus style', await page.evaluate(() => { const s = getComputedStyle(document.activeElement); return [s.outlineStyle, s.outlineWidth, s.outlineColor, s.boxShadow]; }));
  await page.keyboard.press('Escape'); await page.waitForTimeout(200); log('Escape', await desc(page));
  await browser.close();
})();
EOF
