async function pixels(page, probe, clip) {
  const buf = await page.screenshot({ clip });
  return probe.evaluate(async (d) => {
    const img = new Image(); img.src = 'data:image/png;base64,' + d; await img.decode();
    const c = document.createElement('canvas'); c.width = img.width; c.height = img.height; const x = c.getContext('2d'); x.drawImage(img, 0, 0);
    const px = x.getImageData(0, 0, c.width, c.height).data; const counts = {};
    for (let i = 0; i < px.length; i += 4) { const h = '#' + [px[i], px[i+1], px[i+2]].map((v) => v.toString(16).padStart(2, '0')).join(''); counts[h] = (counts[h] || 0) + 1; }
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 8);
  }, buf.toString('base64'));
}
(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, locale: 'es-CO', deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  const probe = await browser.newPage();
  const origins = new Set(); const fonts = [];
  page.on('request', (r) => { const u = new URL(r.url()); origins.add(u.origin); if (r.resourceType() === 'font') fonts.push(u.pathname); });
  await page.goto(BASE + '/');
  await page.waitForTimeout(500);
  log('chooser h1 focus-visible', await page.evaluate(() => { const a = document.activeElement; return [a.tagName, a.matches(':focus-visible'), getComputedStyle(a).outlineStyle]; }));
  await page.goto(BASE + '/co/datos');
  await page.locator('#field-documentType').waitFor();
  log('step1 h1 focus-visible on load', await page.evaluate(() => { const a = document.activeElement; return [a.tagName, a.matches(':focus-visible'), getComputedStyle(a).outlineStyle]; }));
  await fillCO(page);
  log('step2 h1 focus-visible after click', await page.evaluate(() => { const a = document.activeElement; return [a.tagName, a.matches(':focus-visible'), getComputedStyle(a).outlineStyle]; }));
  const radios = page.locator('input[type=radio][name=plan]');
  for (let i = 0; i < 3; i++) {
    const b = await radios.nth(i).boundingBox();
    log('radio ' + i + ' unchecked pixels', await pixels(page, probe, { x: b.x - 2, y: b.y - 2, width: b.width + 4, height: b.height + 4 }));
  }
  log('card bg', await page.evaluate(() => [...document.querySelectorAll('.plan')].map((p) => getComputedStyle(p).backgroundColor + ' / ' + getComputedStyle(p).backgroundImage.slice(0, 40))));
  await radios.nth(0).check();
  const b0 = await radios.nth(0).boundingBox();
  log('radio 0 checked pixels', await pixels(page, probe, { x: b0.x - 2, y: b0.y - 2, width: b0.width + 4, height: b0.height + 4 }));
  // checkbox on step 1 is native too: back later. continue flow
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.getByRole('heading', { level: 1, name: 'Resumen de tu cotización' }).waitFor();
  await page.waitForTimeout(800);
  const cb = page.locator('input[type=checkbox]');
  const cbb = await cb.boundingBox();
  log('terms checkbox unchecked pixels', await pixels(page, probe, { x: cbb.x - 2, y: cbb.y - 2, width: cbb.width + 4, height: cbb.height + 4 }));
  const seg = await page.evaluate(() => [...document.querySelectorAll('input[type=radio]')].map((r) => { const s = getComputedStyle(r); return [r.labels[0]?.textContent.trim(), s.appearance, s.opacity, r.checked]; }));
  log('simulation radios', seg);
  await cb.check();
  await page.getByRole('button', { name: 'Pagar' }).click();
  await page.getByRole('heading', { level: 1, name: 'Pago confirmado' }).waitFor();
  log('origins', [...origins]);
  log('fonts', fonts);
  await browser.close();
})();
EOF
