const { chromium, BASE, log } = require('./common.cjs');
const anim = (page) => page.evaluate(() => {
  const bad = [];
  for (const el of document.querySelectorAll('*')) { const s = getComputedStyle(el); if (s.animationDuration.split(',').some((d) => d.trim() !== '0s') || s.transitionDuration.split(',').some((d) => d.trim() !== '0s')) bad.push(el.tagName + '.' + el.className + ' ' + s.animationDuration + '/' + s.transitionDuration); }
  return { running: document.getAnimations().length, nonZero: bad.slice(0, 5) };
});
const sheetBox = (page, sel) => page.evaluate((sel) => { const p = document.querySelector(sel); if (!p) return null; const r = p.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height, bottom: r.bottom, vw: innerWidth, vh: innerHeight, scrollW: document.documentElement.scrollWidth }; }, sel);
(async () => {
  const browser = await chromium.launch();
  for (const reducedMotion of ['reduce', 'no-preference']) {
    const ctx = await browser.newContext({ viewport: { width: 360, height: 740 }, locale: 'es-CO', reducedMotion, hasTouch: true });
    const page = await ctx.newPage();
    await page.goto(BASE + '/co/datos');
    await page.locator('#field-city').waitFor();
    await page.waitForTimeout(500);
    log(reducedMotion + ' step1 idle', await anim(page));
    await page.locator('#field-city').click();
    await page.waitForTimeout(30);
    log(reducedMotion + ' city sheet t+30ms', await sheetBox(page, '.app-sheet'));
    log(reducedMotion + ' city sheet anim', await anim(page));
    log(reducedMotion + ' sheet panel opacity t+30', await page.evaluate(() => getComputedStyle(document.querySelector('.panel')).opacity));
    await page.waitForTimeout(400);
    log(reducedMotion + ' city sheet settled', await sheetBox(page, '.app-sheet'));
    log(reducedMotion + ' sheet panel opacity settled', await page.evaluate(() => getComputedStyle(document.querySelector('.panel')).opacity));
    log(reducedMotion + ' backdrop', await page.evaluate(() => { const b = document.querySelector('.cdk-overlay-backdrop'); return b ? [b.className, getComputedStyle(b).transitionDuration] : null; }));
    await page.getByRole('button', { name: 'Cerrar' }).click();
    await page.waitForTimeout(100);
    log(reducedMotion + ' after Cerrar focus', await page.evaluate(() => document.activeElement.id));
    await page.getByRole('button', { name: /Elegir fecha/ }).click();
    await page.waitForTimeout(400);
    log(reducedMotion + ' calendar sheet', await sheetBox(page, '.app-sheet'));
    log(reducedMotion + ' calendar anim', await anim(page));
    log(reducedMotion + ' day sizes', await page.evaluate(() => { const d = [...document.querySelectorAll('[role=gridcell]')].map((c) => c.getBoundingClientRect()); return [Math.min(...d.map((r) => r.width)), Math.min(...d.map((r) => r.height))]; }));
    await ctx.close();
  }
  await browser.close();
})();
EOF
cd $S && node probe6.cjs

