S=/private/tmp/claude-502/-Users-cristiansabogal-Proyectos-multicountry-car-insurance/067ab97b-afa7-4129-b205-146de5718a1c/scratchpad; cat > $S/probe7.cjs <<'EOF'
const { chromium, BASE, log } = require('./common.cjs');
const { fillCO } = require('./fill.cjs');
const ind = (page) => page.evaluate(() => ({ url: location.pathname, steps: [...document.querySelectorAll('ol[aria-label="Progreso de la cotización"] li')].map((li) => li.textContent.replace(/\s+/g, ' ').trim() + (li.getAttribute('aria-current') ? ' [current]' : '')) }));
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, locale: 'es-CO' });
  await page.goto(BASE + '/co/datos');
  await page.locator('#field-documentType').waitFor();
  await fillCO(page);
  await page.locator('input[name=plan]').nth(2).check();
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.getByRole('heading', { level: 1, name: 'Resumen de tu cotización' }).waitFor();
  await page.waitForTimeout(800);
  await page.locator('input[type=checkbox]').check();
  await page.getByRole('button', { name: 'Pagar' }).click();
  await page.getByRole('heading', { level: 1, name: 'Pago confirmado' }).waitFor();
  log('confirmation', await ind(page));
  await page.getByRole('button', { name: 'Nueva cotización' }).click();
  await page.waitForTimeout(800);
  log('after Nueva cotización', await ind(page));
  await page.goBack(); await page.waitForTimeout(800);
  log('after back', await ind(page));
  await browser.close();
})();
EOF
